INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:حجب:khalil_kitab_ayn', 'حجب', 'b327776e1bea877f8e1b92453f', 'الحَجْب: كُلٌّ شيءٍ مَنَعَ شَيئاً من شيءٍ فقد حَجَبَه حَجْباً', 'anything that keeps one thing from another', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_cebb23026d031288', '785', NULL, 'blk_kay_fadb3d8f9137e8f8', 0, NULL, 'Marker: head gloss. Reading: keeping from. Primary: keeping back, barrier — 6 of 10 books (al-Khalīl blk_kay_fadb3d8f9137e8f8; Ibn Fāris blk_mqy_34e7b0279c75b068; al-Rāghib blk_mfr_35f580b654a789f8; al-Miṣbāḥ blk_msb_241ab045566e4388; Lane blk_lane_68565e6c2e44408f; al-Jawharī blk_sih_3683f3c179b9152e). Other readings: covering, veil: Ibn Durayd, al-Jawharī, Lisān, al-Qāmūs, Tāj.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:حجب:ibn_durayd_jamharat_lugha', 'حجب', 'b327776e1bea877f8e1b92453f', 'وحجبت الشَّيْء أحجبه حجبا إِذا سترته. والحجاب: السّتْر', 'I hid the thing; a veil is a cover', 'ابن دريد', 'Ibn Durayd, al-Jamhara', 321, 'ibn_durayd_jamharat_lugha', 're_jam_b6cd51d53597a940', '227', NULL, 'blk_jam_585b5df33e51f0a0', 0, NULL, 'Marker: «إذا». Reading: covering. Differs from the main reading (keeping back, barrier).', 'high', 'active');
