INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:حصر:jawhari_sihah', 'حصر', '2e8edde68909b01037499c992f', 'حَصَرَهُ يَحْصُرُهُ حَصْراً: ضيَّق عليه وأحاط به.', 'he hemmed him in and surrounded him', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_3587893c93a56788', '1248', 2, 'blk_sih_dc82b064a6eaad29', 0, NULL, 'Marker: head gloss. Reading: hemming in.', 'high', 'active');
