INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:حصر:qamus_muhit', 'حصر', '2e8edde68909b01037499c992f', 'الحَصْرُ، كالضَّرْبِ والنَّصْرِ: التَّضْييقُ، والحَبْسُ عن السَّفرِ وغيرِهِ', 'hemming in; keeping from travel', 'الفيروزآبادي', 'al-Fīrūzābādī, al-Qāmūs', 817, 'qamus_muhit', 're_qms_e38941b9c14714bc', NULL, NULL, 'blk_qms_8abe2db68243d5d0', 0, NULL, 'Marker: Qāmūs gloss. Reading: hemming in.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:حصر:zabidi_taj_arus', 'حصر', '2e8edde68909b01037499c992f', 'الحَصْرُ، كالضَّرْبِ والنَّصْرِ) ، أَي مِنْ بَابِهَما: (التَّضْيِيقُ)', 'hemming in', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_3a73f043f3eb5137', '24', 11, 'blk_taj_2551bd7b7113e7c7', 0, NULL, 'Marker: Qāmūs gloss. Reading: hemming in.', 'high', 'active');
